ST.xhtml:p:
R_Trriger1(CLK := g_biDustHomeOpen OR bDustHomeOpen);
R_Trriger2(CLK := g_biDustHomeClose);

IF R_Trriger1.Q THEN
  bHomeDone := FALSE;
  g_boDustHomeDone := FALSE;
  nSwitchState := 1;
END_IF;

IF R_Trriger2.Q THEN
  g_boDustHomeDone := FALSE;
END_IF;

CASE nSwitchState OF
  0:
  nSwitchState := 0;
  1:
  Dust_Home.Execute := TRUE;
  Dust_Home.Position := dHomePosition;
  Dust_Home.HomingMode := nHomingMode;
  Dust_Home.bCalibrationCam := g_bDustNegLimit;
  IF Dust_Home.Done THEN
    Dust_Home.Execute := FALSE;
    bHomeDone := TRUE;
    g_boDustHomeDone := TRUE;
    nSwitchState := 0;
  END_IF;

  IF g_bPlcPauseBuffer THEN
    nSwitchState := 10;
  END_IF;

  IF Dust_Home.CommandAborted OR Dust_Home.Error THEN
    Dust_Home.Execute := FALSE;
    g_boDustHomeDone := FALSE;
    nSwitchState := 0;
  END_IF;
  10:
  Dust_Home.Execute := FALSE;
  Dust_Stop.Execute := TRUE;
  IF Dust_Stop.Done AND g_bPlcStartBuffer THEN
    Dust_Stop.Execute := FALSE;
    nSwitchState := 1;
  END_IF;

  IF Dust_Stop.CommandAborted OR Dust_Stop.Error THEN
    Dust_Stop.Execute := FALSE;
    nSwitchState := 0;
  END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nSwitchState := 0;
  bHomeDone := TRUE;
  Dust_Home.Execute := FALSE;
  Dust_Stop.Execute := FALSE;
END_IF;
